import{_ as i,C as t,o as l,c,a2 as a,E as e}from"./chunks/framework.TaNiW7i8.js";const _=JSON.parse('{"title":"Reprendre un projet","description":"","frontmatter":{"title":"Reprendre un projet"},"headers":[],"relativePath":"agent/reprendre.md","filePath":"agent/reprendre.md"}'),d={name:"agent/reprendre.md"};function u(m,r,p,h,g,v){const o=t("AskExample"),s=t("Ask"),n=t("Capture");return l(),c("div",null,[r[0]||(r[0]=a('<h1 id="reprendre-un-projet" tabindex="-1">Reprendre un projet <a class="header-anchor" href="#reprendre-un-projet" aria-label="Permalink to &quot;Reprendre un projet&quot;">​</a></h1><p>Ce parcours sert à repartir là où vous en étiez : l&#39;agent relit ce que la mémoire sait du projet, vous en fait un point, et vous proposez la suite. C&#39;est le premier geste d&#39;une session, voir le <a href="/Kessho/agent/">cycle</a>.</p><h2 id="ce-que-vous-demandez-a-l-agent" tabindex="-1">Ce que vous demandez à l&#39;agent <a class="header-anchor" href="#ce-que-vous-demandez-a-l-agent" aria-label="Permalink to &quot;Ce que vous demandez à l&#39;agent&quot;">​</a></h2>',3)),e(o,{tool:"mem_recall"}),e(o,{tool:"mem_list"}),e(o,{tool:"mem_read_context"}),e(s,{say:"Relis l'historique des sessions de kessho-docs.",verb:"mem_read_history",family:"rappel",args:'{"slug":"kessho-docs"}'}),e(s,{say:"Ouvre l'archive 2026-10-19-14h32-kessho-docs-refonte-du-socle de kessho-docs.",verb:"mem_read_archive",family:"rappel",args:'{"slug":"kessho-docs","filename":"2026-10-19-14h32-kessho-docs-refonte-du-socle"}'}),e(s,{say:"Que sait-on de la structure du dépôt de kessho-docs ?",verb:"mem_get_topology",family:"structure",args:'{"project":"kessho-docs"}'}),e(s,{say:"Ce projet était terminé mais je dois le rouvrir : remets-le parmi les projets actifs.",verb:"mem_historize",family:"session",args:'{"slug":"kessho-docs","revive":true}'}),r[1]||(r[1]=a('<p>Vous n&#39;avez pas besoin de taper ces phrases mot pour mot : avec les procédures livrées par Kessho (voir <a href="/Kessho/agent/connecter.html">Connecter l&#39;agent</a>), une envie de reprendre (« on reprend », « où en étions-nous ? ») ou une question sur le passé (« qu&#39;avait-on décidé ? ») doit suffire à déclencher la reprise, si l&#39;agent les suit. Si le projet visé n&#39;est pas clair, l&#39;agent vous demande de confirmer avant de charger quoi que ce soit.</p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><p>Les outils de cette page <strong>lisent</strong> sans rien écrire, sauf deux : <a href="/Kessho/reference/mcp/session.html#mem-historize"><code>mem_historize</code></a>, qui déplace un projet, et <a href="/Kessho/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> (étape 5), qui récupère, rebase et pousse si la mémoire est un dépôt git.</p><ol><li><strong>Trouver le projet.</strong> Le plus souvent, c&#39;est le slug que vous donnez. Sans slug, <a href="/Kessho/reference/mcp/rappel.html#mem-recall"><code>mem_recall</code></a> rend l&#39;inventaire du vault pour que l&#39;agent vous demande lequel. <a href="/Kessho/reference/mcp/structure.html#mem-list"><code>mem_list</code></a> donne le même inventaire en détail : projets, domaines, phase, dernière session, portée, nombre d&#39;archives. Avec <code>include_archived</code>, il déplie les projets archivés ; avec <code>archived_only</code>, il ne montre qu&#39;eux. D&#39;après la procédure, l&#39;agent essaie aussi le nom du dossier où la session est ouverte.</li><li><strong>Charger le contexte.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-recall"><code>mem_recall</code></a> charge le contexte du projet ou du domaine. La procédure demande à l&#39;agent d&#39;en faire un briefing : dernière session et phase, état, décisions, principes actifs, objectifs ouverts, personnes clés, prochaines étapes. Il termine en proposant la suite (« on reprend à l&#39;étape X ? »).</li><li><strong>Aller plus fin si besoin.</strong><ul><li><a href="/Kessho/reference/mcp/rappel.html#mem-read-context"><code>mem_read_context</code></a> lit seulement le <code>context.md</code>, l&#39;instantané courant, sans briefing : plus léger. <code>slug</code> est obligatoire.</li><li><a href="/Kessho/reference/mcp/rappel.html#mem-read-history"><code>mem_read_history</code></a> lit le <code>history.md</code> : le fil chronologique des sessions, avec leur nombre.</li><li><a href="/Kessho/reference/mcp/rappel.html#mem-read-archive"><code>mem_read_archive</code></a> lit une archive précise (<code>slug</code> et <code>filename</code>, avec ou sans <code>.md</code>), et uniquement dans le dossier <code>archives/</code> du projet.</li><li><a href="/Kessho/reference/mcp/structure.html#mem-get-topology"><code>mem_get_topology</code></a> lit la fiche de topologie du projet (sa pile, ses conventions), éventuellement celle d&#39;une branche (<code>branch</code>). Une fiche absente n&#39;est pas une erreur.</li></ul></li><li><strong>Résumer plusieurs sessions d&#39;un coup.</strong> C&#39;est le rôle de <a href="/Kessho/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a>, voir <a href="/Kessho/agent/chercher.html">Chercher dans la mémoire</a>.</li><li><strong>Se mettre à jour.</strong> Si la mémoire est un dépôt git, la procédure demande à l&#39;agent d&#39;appeler <a href="/Kessho/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> une fois en début de session, pour partir de ce que vos autres postes ont écrit. Hors ligne ou sans distant, il le dit en une ligne et continue. Voir <a href="/Kessho/agent/synchroniser.html">Synchroniser la mémoire</a>.</li></ol><h3 id="un-projet-archive" tabindex="-1">Un projet archivé <a class="header-anchor" href="#un-projet-archive" aria-label="Permalink to &quot;Un projet archivé&quot;">​</a></h3><p>Sans slug explicite, la reprise ignore les projets archivés. Avec un slug explicite, l&#39;agent charge le projet archivé en <strong>lecture</strong> et vous le signale. Pour y écrire à nouveau, il faut d&#39;abord le ramener parmi les actifs : <a href="/Kessho/reference/mcp/session.html#mem-historize"><code>mem_historize</code></a> avec <code>revive: true</code> (sans <code>revive</code>, il déplace au contraire un projet terminé vers <code>10-episodes/archived/</code>). Tant qu&#39;il est archivé, <a href="/Kessho/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a> refuse d&#39;y écrire, et <a href="/Kessho/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a> ne le résume qu&#39;avec <code>from_archived: true</code>.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',7)),e(n,{name:"cles-de-contexte",alt:"L'écran des clés de contexte : un projet avec son résumé et un domaine sans résumé, à donner à un agent pour qu'il retrouve où vous en étiez."}),r[2]||(r[2]=a('<p>L&#39;écran <strong>Clés de contexte</strong> (barre latérale) liste vos projets et domaines : chaque ligne porte son identifiant (le <strong>slug</strong> que vous donnez à l&#39;agent), son résumé, son nombre d&#39;archives et la date de sa dernière session. Il sert de pense-bête avant de dire « on reprend… ». Le détail de l&#39;écran est dans <a href="/Kessho/guide/home.html">Accueil</a>.</p><p>Une ligne « Aucun résumé » veut dire que personne n&#39;a posé de résumé : l&#39;écran le compte, et un agent en pose un avec <a href="/Kessho/reference/mcp/session.html#mem-set-summary"><code>mem_set_summary</code></a> (voir <a href="/Kessho/agent/archiver.html">Archiver une session</a>).</p><p>La reprise elle-même ne change rien à l&#39;écran, puisqu&#39;elle ne fait que lire. Seuls <code>mem_historize</code> (qui déplace le projet) et <code>mem_git_sync</code> (qui peut faire entrer des notes venues d&#39;un autre poste) modifient la mémoire ; le témoin de fraîcheur le montre comme toute écriture d&#39;agent (voir <a href="/Kessho/guide/zones.html">Zones</a>).</p>',3))])}const q=i(d,[["render",u]]);export{_ as __pageData,q as default};
